// La ruta completa es la fuente autoritativa: evita perder clientes al volver a iniciar sesión.
async function loadDeliveriesAuthoritative(){
  const r=await api('/api/deliveries');const d=await r.json();
  if(!r.ok){showLogin(d.error);return}
  const list=d.deliveries||[];
  $('deliveries').innerHTML=list.length?list.map(x=>`<button class="delivery ${x.username===selectedDelivery?'active':''}" data-d="${esc(x.username)}"><span class="avatar">${esc(x.displayName.slice(0,2).toUpperCase())}</span>${esc(x.displayName)}<span class="count">${x.clients.length}</span></button>`).join(''):'<small class="muted no-deliveries">Aún no hay deliverys registrados.</small>';
  document.querySelectorAll('[data-d]').forEach(b=>b.onclick=()=>{selectedDelivery=b.dataset.d;renderDeliveryNav();loadAssignedRoute()});
  if(!selectedDelivery||!list.some(x=>x.username===selectedDelivery))selectedDelivery=list[0]?.username||'';
  if(selectedDelivery){await loadAssignedRoute()}else{route={clients:[],mapUrl:''};render()}
  if(session?.role==='office'){document.querySelectorAll('[data-d]').forEach(item=>{if(item.parentElement?.classList.contains('delivery-row'))return;const row=document.createElement('div');row.className='delivery-row';item.parentNode.insertBefore(row,item);row.appendChild(item);const password=document.createElement('button');password.type='button';password.className='change-delivery-password';password.title='Cambiar contraseña';password.textContent='🔑';password.dataset.deliveryAccountPassword=item.dataset.d;row.appendChild(password);const del=document.createElement('button');del.type='button';del.className='delete-delivery';del.title='Eliminar cuenta';del.textContent='×';del.dataset.deliveryAccountDelete=item.dataset.d;row.appendChild(del)});wireDeliveryAccountActions();styleDeliveryAccountActions()}
}
loadDeliveries=loadDeliveriesAuthoritative;

