// Oficina: el refresco automático nunca puede borrar una edición pendiente.
let manualOfficeRefresh=false;
const loadDeliveriesBeforePendingGuard=loadDeliveries;
async function refreshOfficeManually(){
  if(!session||session.role!=='office')return;
  if(officeUnsavedChanges&&!window.confirm('Hay cambios sin guardar. Si actualizas ahora se descartarán. ¿Continuar?'))return;
  officeUnsavedChanges=false;officeUnsavedDelivery='';mapDraft=null;manualOfficeRefresh=true;
  try{await loadDeliveriesBeforePendingGuard()}finally{manualOfficeRefresh=false}
}
loadDeliveries=async function(){
  if(session?.role==='office'&&officeUnsavedChanges&&!manualOfficeRefresh){$('assignmentHint').textContent='Hay cambios pendientes. Guarda antes de actualizar; usa “Actualizar manualmente” para descartar y recargar.';return}
  return loadDeliveriesBeforePendingGuard()
}
const loadAssignedRouteBeforePendingGuard=loadAssignedRoute;
loadAssignedRoute=async function(){
  if(session?.role==='office'&&officeUnsavedChanges&&!manualOfficeRefresh){$('assignmentHint').textContent='Hay cambios pendientes. Guarda antes de cambiar de delivery; usa “Actualizar manualmente” para descartarlos.';return}
  return loadAssignedRouteBeforePendingGuard()
}
const manualRefreshButton=$('refreshDeliveries');if(manualRefreshButton){manualRefreshButton.textContent='Actualizar manualmente';manualRefreshButton.onclick=refreshOfficeManually}

// Enlaza el botón al guardado final, después de aplicar todos los protectores de edición.
async function saveRouteFinal(){
  if(!session||session.role!=='office')return;
  if(!selectedDelivery){$('assignmentHint').textContent='Primero selecciona un delivery registrado.';return}
  officeSavingChanges=true;
  try{
    const mapUrl=mapDraft!==null?mapDraft.trim():String(route.mapUrl||'');route.mapUrl=mapUrl;
    const r=await api('/api/deliveries/'+encodeURIComponent(selectedDelivery)+'/route',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({clients:route.clients||[],mapUrl})});
    const text=await r.text();let d={};try{d=JSON.parse(text)}catch{}
    if(!r.ok)throw new Error(d.error||'No se pudo guardar la asignación.');
    route=d.delivery||route;mapDraft=null;clearOfficeUnsaved();rememberOfficeRoute(selectedDelivery,route);$('assignmentHint').textContent='Asignación guardada para el delivery.';render();
    await loadDeliveries();
  }catch(error){$('assignmentHint').textContent=error.message||'No se pudo guardar la asignación.'}
  finally{officeSavingChanges=false}
}
saveRoute=saveRouteFinal;
const saveRouteButton=$('saveRoute');if(saveRouteButton)saveRouteButton.onclick=saveRouteFinal;

