async function updateBitacora(file){const result=$('bitacoraResult');result.className='bitacora-result';result.textContent='Leyendo la bitácora sin alterar su formato...';try{if(!window.JSZip)throw new Error('No se pudo cargar el módulo de edición de bitácoras.');const zip=await JSZip.loadAsync(await file.arrayBuffer()),parser=new DOMParser(),serializer=new XMLSerializer(),shared=[];const sharedFile=zip.file('xl/sharedStrings.xml');if(sharedFile){const doc=parser.parseFromString(await sharedFile.async('text'),'application/xml');for(const si of doc.getElementsByTagNameNS('*','si'))shared.push([...si.getElementsByTagNameNS('*','t')].map(x=>x.textContent).join(''))}const wb=parser.parseFromString(await zip.file('xl/workbook.xml').async('text'),'application/xml'),rels=parser.parseFromString(await zip.file('xl/_rels/workbook.xml.rels').async('text'),'application/xml'),targets={};for(const rel of rels.getElementsByTagNameNS('*','Relationship'))targets[rel.getAttribute('Id')]=String(rel.getAttribute('Target')||'').replace(/^\//,'').replace(/^xl\//,'');const operator=String(route.displayName||selectedDelivery||'').trim();const changes={};(route.clients||[]).forEach(c=>{const key=bitacoraXmlClean(c.name);if(key)changes[key]=c});let found=0,changed=0;for(const sheet of wb.getElementsByTagNameNS('*','sheet')){const rid=sheet.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id')||sheet.getAttribute('r:id'),rel=targets[rid],path=rel?(rel.startsWith('xl/')?rel:'xl/'+rel):'';if(!path||!zip.file(path))continue;const doc=parser.parseFromString(await zip.file(path).async('text'),'application/xml'),rows=[...doc.getElementsByTagNameNS('*','row')],header=bitacoraFindHeader(rows,shared);if(!header)continue;for(const row of rows){if(Number(row.getAttribute('r')||0)<=header.row)continue;const cells=[...row.getElementsByTagNameNS('*','c')],byCol=new Map(cells.map(c=>[bitacoraColumnIndex(c.getAttribute('r')),c])),name=bitacoraXmlClean(bitacoraCellText(byCol.get(header.nameCol),shared));const client=changes[name];if(!client)continue;const values=[[header.operatorCol,operator],[header.finalCol,client.status||'En proceso'],[header.statusCol,client.note||'']];found++;for(const [col,value] of values){const cell=byCol.get(col);if(!cell)continue;const old=bitacoraCellText(cell,shared);if(old!==String(value))changed++;bitacoraSetCellText(cell,value,doc)}}zip.file(path,serializer.serializeToString(doc))}const blob=await zip.generateAsync({type:'blob',compression:'DEFLATE'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=file.name.replace(/\.xlsx$/i,'')+'_actualizada.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);result.textContent=`Bitácora preparada: ${found} clientes encontrados, ${changed} valores modificados. Solo se actualizaron Operador, Final y Estatus Alfredo.`}catch(e){result.className='bitacora-result error';result.textContent='No se pudo actualizar la bitácora: '+e.message}}
function forceImportColumnOrderFinal(){const d=$('pasteDialog');if(!d)return;const s=d.querySelector('small'),a=$('pasteArea');if(s)s.textContent='Columnas: Cliente, Teléfono, Dirección, Observación de Oficina.';if(a)a.placeholder='Nombre\tTeléfono\tDirección\tObservación de Oficina'}
forceImportColumnOrderFinal();
const renderWithFinalImportOrder=render;render=function(){renderWithFinalImportOrder();forceImportColumnOrderFinal();normalizeFinalHeaders()};
function normalizeFinalHeaders(){const head=document.querySelector('thead tr');if(!head)return;const labels=['Cliente','Teléfono','Dirección','Observación de Oficina','Estado','Observación de Delivery'];[...head.children].slice(labels.length).forEach(x=>x.remove());[...head.children].forEach((x,i)=>{if(labels[i])x.textContent=labels[i]});document.querySelectorAll('#rows tr').forEach(row=>{if(row.children.length>labels.length)row.children[3]?.remove();if(row.children.length>=3)row.insertBefore(row.children[2],row.children[1])})}
function photoFileName(client){return(String(client?.name||'foto').replace(/[^wáéíóúñü -]+/gi,'').trim().replace(/\s+/g,'_')||'foto')+'.jpg'}
function downloadDeliveryPhoto(photo,name){const a=document.createElement('a');a.href=photo;a.download=name||'foto.jpg';document.body.appendChild(a);a.click();a.remove()}
async function shareDeliveryPhoto(photo,name){try{if(window.pcPhoto?.share){const result=await window.pcPhoto.share(photo);if(result?.ok){alert('Imagen copiada al portapapeles. Puedes pegarla donde quieras compartirla.');return}throw new Error(result?.error||'No se pudo copiar la imagen.')}const response=await fetch(photo),blob=await response.blob(),file=new File([blob],name||'foto.jpg',{type:blob.type||'image/jpeg'});if(navigator.share&&(!navigator.canShare||navigator.canShare({files:[file]}))){await navigator.share({title:name||'Foto de entrega',files:[file]});return}if(navigator.clipboard?.write&&window.ClipboardItem){await navigator.clipboard.write([new ClipboardItem({[blob.type||'image/jpeg']:blob})]);alert('Imagen copiada al portapapeles. Puedes pegarla donde quieras compartirla.');return}downloadDeliveryPhoto(photo,name);alert('Imagen descargada. Puedes adjuntarla para compartirla.')}catch(error){if(error?.name!=='AbortError')alert('No se pudo preparar la imagen para compartirla. Puedes usar Descargar.')}}
function photoControls(client,photo){const box=document.createElement('div');box.className='delivery-photo-tools';const download=document.createElement('button');download.type='button';download.className='photo-button';download.textContent='Descargar';download.title='Descargar imagen';download.onclick=()=>downloadDeliveryPhoto(photo,photoFileName(client));const share=document.createElement('button');share.type='button';share.className='photo-button';share.textContent='Compartir';share.title='Compartir imagen';share.onclick=()=>shareDeliveryPhoto(photo,photoFileName(client));box.append(download,share);return box}
const wireDeliveryPhotoPreviewsWithActions=wireDeliveryPhotoPreviews;wireDeliveryPhotoPreviews=function(){wireDeliveryPhotoPreviewsWithActions();if(!session||session.role!=='office')return;document.querySelectorAll('[data-note]').forEach(input=>{const client=(route.clients||[]).find(c=>String(c.id)===input.dataset.note),photo=client?.notePhoto;if(!photo||input.parentElement.querySelector('.delivery-photo-tools'))return;input.parentElement.appendChild(photoControls(client,photo))})}
const openClientDetailsWithPhotoActions=openClientDetails;openClientDetails=function(id){openClientDetailsWithPhotoActions(id);const client=(route.clients||[]).find(c=>String(c.id)===String(id)),body=$('clientDetailBody');if(!client?.notePhoto||!body)return;const row=document.createElement('div');row.className='client-detail-row';const label=document.createElement('b');label.textContent='Foto de entrega';const content=document.createElement('span');const image=document.createElement('img');image.className='delivery-photo-preview';image.src=client.notePhoto;image.alt='Foto de entrega';image.onclick=()=>{ensureDeliveryPhotoViewer();$('deliveryPhotoViewer').querySelector('img').src=client.notePhoto;$('deliveryPhotoViewer').showModal()};content.append(image,photoControls(client,client.notePhoto));row.append(label,content);body.appendChild(row)};
function updateNotice(text){if($('assignmentHint'))$('assignmentHint').textContent=text;else if($('whoami'))$('whoami').textContent=text}
async function checkForAppUpdate(manual=false){if(!window.pcUpdater)return;try{const result=await window.pcUpdater.check();if(!result.available){if(manual)updateNotice(result.configured?'La aplicación ya está actualizada.':'Actualizaciones todavía no configuradas.');return}const key='appoficina-update-seen-'+result.manifest.version;if(!manual&&sessionStorage.getItem(key))return;if(officeUnsavedChanges||deliveryUnsavedChanges){updateNotice('Hay cambios pendientes. Guarda los cambios antes de instalar la actualización.');return}sessionStorage.setItem(key,'1');const notes=result.manifest.notes?`\n\n${result.manifest.notes}`:'';if(!window.confirm(`Aviso: se encontró una nueva actualización (${result.manifest.version}). ¿Deseas instalarla?${notes}`))return;updateNotice('Descargando actualización y verificando su integridad…');await window.pcUpdater.install(result.manifestUrl,result.manifest);alert('La actualización se instalará al cerrar la aplicación.');}catch(error){if(manual)updateNotice('No se pudo comprobar la actualización: '+error.message)}}
function ensureUpdateButton(){if($('appUpdateButton'))return;const header=document.querySelector('header');if(!header)return;const button=document.createElement('button');button.id='appUpdateButton';button.type='button';button.className='secondary';button.textContent='Buscar actualización';button.onclick=()=>checkForAppUpdate(true);header.insertBefore(button,header.lastElementChild)}
setTimeout(()=>{ensureUpdateButton();checkForAppUpdate()},5000);
